glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
layout(std140) uniform BorderUniform {
  vec4 borderColor;
  vec4 borderConfig;
  vec4 filterConfig;
  vec4 outlineConfig;
  vec4 worldAxisX;
  vec4 worldAxisY;
};
vec4 vert () {
  vec2 size = max(borderConfig.xy, vec2(1.0));
  vec2 sourceSize = max(filterConfig.xy, vec2(1.0));
  float width = clamp(borderConfig.z, 0.0, 8.0);
  float smoothing = clamp(filterConfig.z, 0.0, 2.0);
  float aaStrength = clamp(filterConfig.w, 0.5, 2.0);
  vec4 worldPosition = vec4(a_position, 1.0);
  #if USE_LOCAL
    worldPosition = cc_matWorld * worldPosition;
  #endif
  vec4 clip = cc_matViewProj * worldPosition;
  vec4 clipAxisX =
    cc_matViewProj * vec4(worldAxisX.xyz, 0.0);
  vec4 clipAxisY =
    cc_matViewProj * vec4(worldAxisY.xyz, 0.0);
  float safeW = max(abs(clip.w), 0.000001);
  vec2 ndc = clip.xy / safeW;
  vec2 screenScale =
    0.5 * cc_nativeSize.xy * cc_viewPort.zw / safeW;
  vec2 pixelAxisX =
    (clipAxisX.xy - ndc * clipAxisX.w) * screenScale;
  vec2 pixelAxisY =
    (clipAxisY.xy - ndc * clipAxisY.w) * screenScale;
  float determinant = abs(
    pixelAxisX.x * pixelAxisY.y -
    pixelAxisX.y * pixelAxisY.x
  );
  vec2 localPerPixel = vec2(
    abs(pixelAxisY.x) + abs(pixelAxisY.y),
    abs(pixelAxisX.x) + abs(pixelAxisX.y)
  ) / max(determinant, 0.000001);
  vec2 padding =
    vec2(width) +
    (smoothing + 1.0) * size / sourceSize +
    (aaStrength + 1.0) * localPerPixel;
  vec2 corner = a_texCoord * 2.0 - 1.0;
  worldPosition.xyz +=
    worldAxisX.xyz * corner.x * padding.x;
  worldPosition.xyz -=
    worldAxisY.xyz * corner.y * padding.y;
  v_uv = a_texCoord + corner * padding / size;
  v_color = a_color;
  return cc_matViewProj * worldPosition;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform BorderUniform {
  vec4 borderColor;
  vec4 borderConfig;
  vec4 filterConfig;
  vec4 outlineConfig;
  vec4 worldAxisX;
  vec4 worldAxisY;
};
vec4 sampleImage(vec2 uv) {
  float inside =
    step(0.0, uv.x) *
    step(uv.x, 1.0) *
    step(0.0, uv.y) *
    step(uv.y, 1.0);
  vec4 color = CCSampleWithAlphaSeparated(
    cc_spriteTexture,
    clamp(uv, vec2(0.0), vec2(1.0))
  );
  return color * inside;
}
float contourAlpha(vec2 uv) {
  vec2 sourceSize = max(filterConfig.xy, vec2(1.0));
  float smoothing = clamp(filterConfig.z, 0.0, 2.0);
  if (smoothing <= 0.0) {
    return sampleImage(uv).a;
  }
  vec2 h = 0.5 * smoothing / sourceSize;
  return 0.25 * (
    sampleImage(uv + vec2(-h.x, -h.y)).a +
    sampleImage(uv + vec2( h.x, -h.y)).a +
    sampleImage(uv + vec2(-h.x,  h.y)).a +
    sampleImage(uv + vec2( h.x,  h.y)).a
  );
}
float alphaDerivative(float value) {
    return fwidth(value);
}
vec4 frag () {
  vec4 base = sampleImage(v_uv);
  vec2 size = max(borderConfig.xy, vec2(1.0));
  float width = clamp(borderConfig.z, 0.0, 8.0);
  float cutoff = clamp(borderConfig.w, 0.001, 0.98);
  float aaStrength = clamp(filterConfig.w, 0.5, 2.0);
  float originalAlpha = contourAlpha(v_uv);
  float expandedAlpha = originalAlpha;
  for (int y = -4; y <= 4; y++) {
    for (int x = -4; x <= 4; x++) {
      if (x != 0 || y != 0) {
        vec2 p = vec2(float(x), float(y)) / 4.0;
        p /= max(1.0, length(p));
        vec2 offset = p * width / size;
        expandedAlpha = max(
          expandedAlpha,
          contourAlpha(v_uv + offset)
        );
      }
    }
  }
  float halfAA = max(
    0.5 * aaStrength * alphaDerivative(expandedAlpha),
    0.00001
  );
  float low = max(0.0, cutoff - halfAA);
  float high = min(1.0, cutoff + halfAA);
  float outerCoverage =
    smoothstep(low, high, expandedAlpha);
  float innerAA = min(
    max(0.5 * aaStrength * alphaDerivative(originalAlpha), 0.00001),
    min(cutoff, 1.0 - cutoff)
  );
  float originalCoverage = smoothstep(
    max(0.0, cutoff - innerAA),
    min(1.0, cutoff + innerAA),
    originalAlpha
  );
  outerCoverage *= 1.0 -
    clamp(outlineConfig.x, 0.0, 1.0) * originalCoverage;
  float borderAlpha =
    outerCoverage * clamp(borderColor.a, 0.0, 1.0);
  borderAlpha *= step(0.00001, width);
  float visibleBorder = borderAlpha * (1.0 - base.a);
  float outputAlpha = base.a + visibleBorder;
  vec3 premultiplied =
    base.rgb * base.a +
    borderColor.rgb * visibleBorder;
  vec3 outputRGB =
    premultiplied / max(outputAlpha, 0.00001);
  return vec4(outputRGB, outputAlpha) * v_color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

